function rkChart(h){ if(h.length<2) return `<div class="sm mut">${_t("История появится через пару месяцев.")}</div>`; const d=h.slice(-60); const W=300,H=90; const mx=Math.max(...d.map(x=>x[2])), mn=Math.min(...d.map(x=>x[2])); const sp=Math.max(4,mx-mn);
 const x=i=>i/(d.length-1)*W, y=r=>6+(r-mn)/sp*(H-12); const pts=d.map((v,i)=>x(i).toFixed(1)+','+y(v[2]).toFixed(1)).join(' ');
 return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="#3fb950" stroke-width="2"/></svg><div class="sm mut" style="display:flex;justify-content:space-between"><span>${N.fmtD(d[0][0],1)} · #${d[0][2]}</span><span>${_t("лучшее #{0} · худшее",mn)} #${mx}</span><span>#${d[d.length-1][2]}</span></div>`; }
