const MENT=[_t("Глухая оборона"),_t("Оборона"),_t("Баланс"),_t("Атака"),_t("Все в атаку")], PRESS=[_t("Низкий"),_t("Средний"),_t("Высокий")], TEMPO=[_t("Медленный"),_t("Обычный"),_t("Быстрый")], STYLE={mix:_t("Смешанный"),short:_t("Короткий пас"),long:_t("Длинные передачи"),counter:_t("Контратаки")};
const INSTR={'':_t("Стандартно"),att:_t("Больше атаковать"),hold:_t("Держать позицию"),free:_t("Свободная роль"),mark:_t("Персональная опека")};
function tacPanel(tac,fn){ const sel=(lab,key,opts,val)=>`<div style="margin:6px 0"><div class="sm mut">${lab}</div><select onchange="${fn}('${key}',this.value)">${opts.map(([v,n])=>`<option value="${v}" ${String(v)===String(val)?'selected':''}>${n}</option>`).join('')}</select></div>`;
 return sel(_t("Настрой"),'ment',MENT.map((n,i)=>[i-2,n]),tac.ment)+sel(_t("Прессинг"),'press',PRESS.map((n,i)=>[i,n]),tac.press)+sel(_t("Темп"),'tempo',TEMPO.map((n,i)=>[i,n]),tac.tempo)+sel(_t("Стиль"),'style',Object.entries(STYLE),tac.style); }
function pitchHTML(form,ids){ const F=N.FORMS[form]; return `<div class="pitch" id="pitch" dir="ltr"><div class="ln" style="left:-2px;right:-2px;top:50%;height:0"></div><div class="spot" style="left:50%;top:50%"></div><div class="ln" style="left:38%;width:24%;bottom:-2px;height:6%"></div><div class="ln" style="left:38%;width:24%;top:-2px;height:6%"></div><div class="ln" style="left:35%;width:30%;top:44%;height:12%;border-radius:50%"></div><div class="ln" style="left:22%;width:56%;bottom:-2px;height:15%"></div><div class="ln" style="left:22%;width:56%;top:-2px;height:15%"></div>
 ${F.map(([role,x,y],i)=>{ const p=ids[i]&&S.P[ids[i]]; const v=p?Math.round(N.roleOvr(p,role)):0; const bad=p&&(N.compat(p.pos,role)<0.9||p.inj||p.sus);
  return `<div class="tok ${role==='GK'?'gk':''} ${bad?'bad':''} ${st.sel&&st.sel.k==='s'&&st.sel.i===i?'sel':''}" data-slot="${i}" style="left:${x}%;top:${96-y*0.9}%">${p?N.teamShirt(S.me,v,role==='GK'):N.shirt('rgba(255,255,255,.18)','rgba(255,255,255,.3)','+')}<div class="nmt">${p?esc(short(p)):'—'}</div><div class="rl">${N.POS[role][0]}${p&&S.u.instr[p.id]?' ★':''}</div></div>`; }).join('')}</div>`; }
SCR.tactics=()=>{ top(_t("Тактика")); if(!S.u.xi||(!N.validXI()&&S.u.xi.s.every(id=>!id))) N.autoXI(); const x=S.u.xi; x.b=S.u.call.filter(id=>!x.s.includes(id)); const bench=x.b.map(id=>S.P[id]).filter(Boolean);
 const xiOvr=Math.round(x.s.reduce((s,id,i)=>s+(id?N.roleOvr(S.P[id],N.FORMS[x.form][i][0]):0),0)/11);
 V().innerHTML=`<div class="card"><div class="row" style="border:0"><select style="flex:1" onchange="UI.setForm(this.value)">${Object.keys(N.FORMS).map(f=>`<option ${f===x.form?'selected':''}>${f}</option>`).join('')}</select><span class="ovr">${xiOvr}</span><button class="btn sm" onclick="UI.autoXIbtn()">${_t("Автосостав")}</button></div>
 <div class="sm mut" style="margin:4px 0">${_t("Перетащите игрока на другого или нажмите двух игроков по очереди, чтобы поменять их местами. Повторное нажатие — индивидуальная установка. Красная обводка — не своя позиция / недоступен.")}</div>
 ${pitchHTML(x.form,x.s)}</div>
 <div class="card"><h3>${_t("Запасные")} (${bench.length})</h3><div class="bench">${bench.map(p=>`<div class="bp ${st.sel&&st.sel.k==='b'&&st.sel.id===p.id?'sel':''}" data-pid="${p.id}">${posB(p)} ${esc(short(p))} <b>${p.o}</b>${p.inj?' 🚑':''}${p.sus?' 🟥':''}</div>`).join('')||`<span class="mut sm">${_t("Вызовите больше игроков")}</span>`}</div></div>
 <div class="card"><h3>${_t("Командные установки")}</h3>${tacPanel(S.u.tac,'UI.setTac')}</div>`; bindPitch(); };
function setForm(f){ const x=S.u.xi; const ps=x.s.map(id=>S.P[id]).filter(Boolean);
 const F=N.FORMS[f]; const used=new Set(); const ns=new Array(11).fill(null); const order=F.map((_,i)=>i).sort((a,b)=>(F[a][0]==='GK'?-1:0)-(F[b][0]==='GK'?-1:0));
 for(const i of order){ const role=F[i][0]; let best=null,bv=-1; for(const p of ps){ if(used.has(p.id))continue; const v=N.roleOvr(p,role); if(v>bv){bv=v;best=p;} } if(best){used.add(best.id);ns[i]=best.id;} }
 x.form=f; x.s=ns; refresh(); }
function autoXIbtn(){ N.autoXI(S.u.xi&&S.u.xi.form); refresh(); toast(_t("Лучший состав выставлен")); }
function setTac(k,v){ S.u.tac[k]=k==='style'?v:+v; }
function swapSel(a,b){ const x=S.u.xi; const A=a.k==='s'?x.s[a.i]:a.id, B=b.k==='s'?x.s[b.i]:b.id;
 if(a.k==='s'&&b.k==='s'){ x.s[a.i]=B; x.s[b.i]=A; } else if(a.k==='s'){ x.s[a.i]=B; } else if(b.k==='s'){ x.s[b.i]=A; }
 x.b=S.u.call.filter(id=>!x.s.includes(id)); }
function tapSel(s){ if(st.sel){ const a=st.sel; st.sel=null; if(a.k==='s'&&s.k==='s'&&a.i===s.i){ const id=S.u.xi.s[s.i]; if(id) instrModal(id); return refresh(); } if(a.k==='b'&&s.k==='b'){ st.sel=s; return refresh(); } swapSel(a,s); return refresh(); } st.sel=s; refresh(); }
function instrModal(id){ const p=S.P[id]; modal(`<h2>${esc(p.n)}</h2><div class="sm mut">${_t("Индивидуальная установка")}</div>${Object.entries(INSTR).map(([k,n])=>`<div class="row c" onclick="UI.setInstr(${id},'${k}')"><span>${(S.u.instr[id]||'')===k?'🔘':'⚪'}</span><div class="f1">${n}</div></div>`).join('')}<div style="height:6px"></div><button class="btn gh w" onclick="UI.player(${id})">${_t("Карточка игрока")}</button>`); }
function setInstr(id,k){ if(k)S.u.instr[id]=k; else delete S.u.instr[id]; closeM(); refresh(); }
function bindPitch(){ const root=V(); let drag=null;
 root.querySelectorAll('.tok,.bp').forEach(el=>{ el.addEventListener('pointerdown',e=>{ e.preventDefault(); const s=el.dataset.slot!==undefined?{k:'s',i:+el.dataset.slot}:{k:'b',id:+el.dataset.pid}; drag={el,s,x:e.clientX,y:e.clientY,moved:false}; try{el.setPointerCapture(e.pointerId)}catch(_){} });
  el.addEventListener('pointermove',e=>{ if(!drag||drag.el!==el)return; const dx=e.clientX-drag.x,dy=e.clientY-drag.y; if(!drag.moved&&Math.hypot(dx,dy)>8){drag.moved=true;el.classList.add('drag');} if(drag.moved){ el.style.transform=el.classList.contains('bp')?`translate(${dx}px,${dy}px)`:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`; } });
  el.addEventListener('pointerup',e=>{ if(!drag||drag.el!==el)return; const d=drag; drag=null; if(!d.moved){ tapSel(d.s); return; } el.style.visibility='hidden'; const t=document.elementFromPoint(e.clientX,e.clientY); el.style.visibility=''; const tgt=t&&t.closest('.tok,.bp'); st.sel=null;
   if(tgt&&tgt!==el){ const s2=tgt.dataset.slot!==undefined?{k:'s',i:+tgt.dataset.slot}:{k:'b',id:+tgt.dataset.pid}; swapSel(d.s,s2); } refresh(); }); }); }
