 <div class="card"><h3>${_t("Впереди")}</h3>${pend.map(c=>`<div class="row"><div class="f1">${esc(c.n)}</div><span class="sm mut">${c.gd?N.fmtD(c.gd[0],1):''}</span></div>`).join('')||'<div class="mut sm">—</div>'}</div>
