SCR.prematch=(fid)=>{ const f=S.F.find(x=>x.id===fid); if(!f||f.r)return home(); top(_t("Перед матчем")); const opp=f.h===S.me?f.a:f.h; const o=T(opp);
 const n=S.u.call.length; const ok=n>=18&&n<=23; if(!N.validXI()) N.autoXI(S.u.xi&&S.u.xi.form);
 const os=N.setup(opp,f); const key=os.on.slice().sort((a,b)=>b.p.o-a.p.o).slice(0,3);
 const x=S.u.xi; const unavail=S.u.call.map(id=>S.P[id]).filter(p=>p&&(p.inj||p.sus));
 const h2h=S.F.filter(z=>z.u&&z.r&&(z.h===opp||z.a===opp)); const form=os.on.length?Math.round(os.on.reduce((s,e)=>s+e.p.o,0)/os.on.length):0;
 V().innerHTML=`<div class="card nm"><h3>${esc(cName(f))} · ${esc(f.st)}</h3><div class="vs"><div><div class="flag">${T(f.h).f}</div><div class="tn">${esc(T(f.h).n)}</div>${stars(T(f.h))}<div class="sm mut">${_t("Эло {0}",T(f.h).elo)}</div></div><div class="b" style="font-size:22px">VS</div><div><div class="flag">${T(f.a).f}</div><div class="tn">${esc(T(f.a).n)}</div>${stars(T(f.a))}<div class="sm mut">${_t("Эло {0}",T(f.a).elo)}</div></div></div><div class="ctr sm mut">${N.fmtD(f.d)} · ${f.neu?_t("нейтральное поле"):f.h===S.me?_t("домашний матч"):_t("выездной матч")}${koInfo(f)}</div>${venueInfo(f)}</div>
 <div class="card"><h3>${_t("Скаутский отчёт")}: ${esc(o.n)}</h3><div class="sm">${_t("Схема")}: <b>${o.form}</b> · ${_t("средняя сила основы")}: <b>${form}</b><br>${_t("Ключевые игроки")}: ${key.map(e=>esc(e.p.n)+' ('+N.POS[e.p.pos][0]+', '+e.p.o+')').join(', ')}${h2h.length?`<br>${_t("Личные встречи при вас")}: ${h2h.map(z=>z.r.hg+':'+z.r.ag).join(', ')}`:''}</div></div>
 <div class="card"><h3>${_t("Наш состав")} · ${x.form}</h3>${x.s.map((id,i)=>{const p=S.P[id];const role=N.FORMS[x.form][i][0];return p?`<div class="row sm"><span class="pos p${N.POS[role][1]}">${N.POS[role][0]}</span><div class="f1">${esc(p.n)}${p.prom?' 🤝':''}</div><span class="${p.fit<75?'red':'mut'}">${Math.round(p.fit)}%</span><span class="ovr">${Math.round(N.roleOvr(p,role))}</span></div>`:''}).join('')}
 ${unavail.length?`<div class="sm red" style="margin-top:6px">${_t("Недоступны")}: ${unavail.map(p=>esc(short(p))+(p.inj?' 🚑':' 🟥')).join(', ')}</div>`:''}</div>
 ${ok?'':`<div class="card red">${_t("Вызов должен содержать 18–23 игрока (сейчас {0}).",n)} <button class="btn sm" onclick="UI.autoCall()">${_t("Автовызов")}</button></div>`}
 <div class="grid2"><button class="btn" onclick="UI.go('squad')">👥 ${_t("Вызов")}</button><button class="btn" onclick="UI.go('tactics')">📋 ${_t("Тактика")}</button></div><div style="height:8px"></div>
 <button class="btn g w big" ${ok?'':'disabled'} onclick="UI.startMatch(${fid})">⚽ ${_t("Начать матч")}</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.quickMatch(${fid})" ${ok?'':'disabled'}>⏩ ${_t("Быстрая симуляция")}</button>`; };
function koInfo(f){ if(!f.ko) return ''; if(f.leg===1) return ` · ${_t("1-й матч из двух (по сумме)")}`; if(f.leg===2){ const l=S.F.find(x=>x.id===f.l1); return ` · ${_t("ответный матч: первый {0}; при равенстве суммы — д.в. и пенальти (гол на выезде не учитывается)",(l&&l.r?T(l.h).n+' '+l.r.hg+':'+l.r.ag+' '+T(l.a).n:'—'))}`; } return ` · ${_t("плей-офф: при ничьей — д.в. и пенальти")}`; }
function venueInfo(f){ const v=N.venue(f); return `<div class="ctr sm mut">${N.WXN[v.wx]||''} · ${_t("стадион на {0} мест · ожидается {1} зрителей{2}",num(v.cap),num(v.att),f.neu?'':(v.fill>0.8?` · ${_t("аншлаг, мощная поддержка хозяев")}`:v.fill<0.45?` · ${_t("полупустые трибуны")}`:''))}</div>`; }
const SPD=[800,400,180,70];
function startMatch(fid,quick){ const f=S.F.find(x=>x.id===fid); const h=N.setup(f.h,f), a=N.setup(f.a,f); const side=f.h===S.me?0:1;
 const M=new N.Match(h,a,N.matchOpts(f)); st.m={M,f,side,spd:PREF.spd||0,paused:true,timer:null};
 if(quick){ M.o.autoUser=true; M.sim(); return endMatch(); }
 st.stack.push(['hub',null]); st.cur='match'; renderMatch(); setTimeout(()=>play(),600); }
function quickMatch(fid){ startMatch(fid,true); }
function evIc(t){ const C={goal:N.ballSvg(),yc:N.cardSvg('#f6c445'),rc:N.cardSvg('#ff4040'),sub:`<span class="grn">${ic('repeat')}</span>`,inj:`<span class="red">${ic('heart-pulse')}</span>`,var:`<span style="color:#38d2e8">${ic('tv')}</span>`,save:`<span style="color:#9fc3ff">${ic('shield')}</span>`,miss:`<span class="mut">${ic('target')}</span>`,pk:`<span class="gold">${ic('target')}</span>`,corner:`<span class="mut">${ic('flag')}</span>`,off:`<span class="mut">${ic('flag')}</span>`,foul:`<span class="org">${ic('triangle-alert')}</span>`,kick:`<span class="mut">${ic('timer')}</span>`,ht:`<span class="mut">${ic('timer')}</span>`,ft:`<span class="mut">${ic('timer')}</span>`,add:`<span class="mut">${ic('timer')}</span>`}; return C[t]||`<span class="dim">${ic('activity')}</span>`; }
function kitPair(f){ const a=N.kit(f.h), b=N.kit(f.a); const d=(x,y)=>{ const p=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)); const [r1,g1,b1]=p(x),[r2,g2,b2]=p(y); return Math.abs(r1-r2)+Math.abs(g1-g2)+Math.abs(b1-b2); }; return [a,d(a[0],b[0])<120?[b[1],b[0]]:b]; }
function renderMatch(){ const {M,f}=st.m; nav(); const c=S.C[f.c]; $('#top').innerHTML=`<div class="ttl">${esc(cName(f))}</div><div class="dt">${esc(f.st)}</div>`;
 const L='rgba(255,255,255,.45)'; const kp=kitPair(f); st.m.kp=kp; st.m.mom=[]; st.m.mv=0; const v=N.venue(f);
 const side=(t,k,cl)=>`<div class="side ${cl}"><span class="kit" style="background:linear-gradient(${k[0]},${k[0]} 60%,${k[1]} 60%)"></span>${T(t).f}<span class="nmx">${esc(T(t).n)}</span></div>`;
 V().innerHTML=`<div class="bcast"><div class="strip">${c?N.badge(c,'sm'):''}<span class="f1">${esc(cName(f))} · ${esc(f.st)}</span><span>${N.WXN[v.wx]||''}</span></div>
 <div class="main">${side(f.h,kp[0],'h')}<div class="score" id="msc"><span id="sc0">0</span><span class="sep">:</span><span id="sc1">0</span></div>${side(f.a,kp[1],'a')}</div>
 <div class="clock"><span class="live"></span><span id="mmin">0'</span><span class="pens" id="mpen"></span></div></div>
 <div class="mpitch" id="mp" dir="ltr"><div style="position:absolute;left:50%;top:0;bottom:0;border-left:2px solid ${L}"></div><div style="position:absolute;left:50%;top:50%;width:17%;aspect-ratio:1;transform:translate(-50%,-50%);border:2px solid ${L};border-radius:50%"></div><div style="position:absolute;left:0;top:22%;width:15.7%;height:56%;border:2px solid ${L};border-left:0"></div><div style="position:absolute;right:0;top:22%;width:15.7%;height:56%;border:2px solid ${L};border-right:0"></div><div style="position:absolute;left:0;top:37%;width:5.2%;height:26%;border:2px solid ${L};border-left:0"></div><div style="position:absolute;right:0;top:37%;width:5.2%;height:26%;border:2px solid ${L};border-right:0"></div><div style="position:absolute;left:0;top:44%;width:1.2%;height:12%;background:rgba(255,255,255,.7)"></div><div style="position:absolute;right:0;top:44%;width:1.2%;height:12%;background:rgba(255,255,255,.7)"></div><div class="ball" id="ball" style="left:50%;top:50%"></div></div>
 <div class="mom" dir="ltr"><span class="lab">${_t("Моментум")}</span><svg id="mom" viewBox="0 0 120 60" preserveAspectRatio="none"></svg></div>
 <div class="tline" id="tl" dir="ltr"><div class="ax"><i id="tlp" style="width:0"></i></div><div class="ht" style="left:50%"></div></div>
 <div class="ctl"><button class="btn" id="bpp" onclick="UI.pp()" aria-label="pause">${ic('pause')}</button><button class="btn" id="bsp" onclick="UI.spd()">${ic('fast-forward')} ×${[1,2,4,8][st.m.spd]}</button><button class="btn" onclick="UI.subsM()">${ic('repeat')} ${_t("Замены")}</button><button class="btn" onclick="UI.tacM()">${ic('clipboard-list')} ${_t("Тактика")}</button></div>
 <div class="card" style="padding:10px 12px"><div class="slab">${_t("Владение")}</div><div class="sbar"><span class="v" id="pss0">50%</span><div class="tr" style="background:${kp[1][0]}"><i id="pssb" style="width:50%;background:${kp[0][0]}"></i></div><span class="v" id="pss1">50%</span></div><div class="mstats" id="mst"></div></div>
 <div class="card feed" id="feed"></div><button class="btn r w" onclick="UI.simEnd()">${ic('fast-forward')} ${_t("Досимулировать до конца")}</button>`;
 drawPlayers(); }
function momDraw(){ const m=st.m, M=m.M; const svg=$('#mom'); if(!svg)return; const T0=M.extra?120:90; const pts=[]; for(let i=0;i<=Math.max(M.min,1);i++){ if(m.mom[i]!==undefined) pts.push([i/T0*120, 30-Math.max(-1,Math.min(1,m.mom[i]))*27]); }
 if(pts.length<2){ svg.innerHTML=''; return; } const d='M'+pts[0][0].toFixed(1)+',30 '+pts.map(p=>'L'+p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')+' L'+pts[pts.length-1][0].toFixed(1)+',30 Z';
 const [a,b]=m.kp; svg.innerHTML=`<defs><clipPath id="mt"><rect x="0" y="0" width="120" height="30"/></clipPath><clipPath id="mb"><rect x="0" y="30" width="120" height="30"/></clipPath></defs><line x1="0" x2="120" y1="30" y2="30" stroke="rgba(255,255,255,.2)" stroke-width=".4"/><line x1="${45/T0*120}" x2="${45/T0*120}" y1="0" y2="60" stroke="rgba(255,255,255,.15)" stroke-width=".4" stroke-dasharray="1.5 1.5"/><path d="${d}" fill="${a[0]}" fill-opacity=".85" clip-path="url(#mt)"/><path d="${d}" fill="${b[0]}" fill-opacity=".85" clip-path="url(#mb)"/>${M.ev.filter(e=>e.t==='goal').map(e=>`<circle cx="${(e.m/T0*120).toFixed(1)}" cy="${e.side===0?5:55}" r="2.2" fill="#fff"/>`).join('')}`; }
function tlAdd(evs){ const m=st.m, M=m.M; const tl=$('#tl'); if(!tl)return; const T0=M.extra?120:90; const p=$('#tlp'); if(p)p.style.width=Math.min(100,M.min/T0*100)+'%';
 for(const e of evs){ if(!['goal','yc','rc','sub','inj','var'].includes(e.t))continue; const d=document.createElement('div'); d.className='e '+(e.side===0?'h':'a'); d.style.left=Math.min(100,e.m/T0*100)+'%'; d.title=e.m+"' "+e.txt; d.innerHTML=evIc(e.t); tl.appendChild(d); } }
function drawPlayers(){ const {M}=st.m; const mp=$('#mp'); if(!mp)return; mp.querySelectorAll('.pl').forEach(e=>e.remove());
 for(const s of [0,1]) M.t[s].on.forEach((e,i)=>{ if(e.off)return; const d=document.createElement('div'); d.className='pl'; d.dataset.s=s; d.dataset.i=i; const k=(st.m.kp||[['#3d8bff','#fff'],['#ff5a5f','#fff']])[s]; d.style.background=e.role==='GK'?'#f6c445':k[0]; d.style.borderColor=e.role==='GK'?'#222':k[1]; d.title=e.p.n; mp.appendChild(d); });
 posPlayers(); }
function roleXY(role,i,on){ const D={GK:[2,50],CB:[20,50],LB:[26,14],RB:[26,86],DM:[38,50],CM:[50,50],AM:[64,50],LM:[56,12],RM:[56,88],LW:[76,15],RW:[76,85],ST:[84,50]};
 const same=on.filter(e=>!e.off&&e.role===role); const k=same.indexOf(on[i]); const n=same.length; let [x,y]=D[role]; if(n>1&&['CB','CM','ST','DM','AM'].includes(role)){ y=50+(k-(n-1)/2)*(role==='CB'?20:22); } return [x,y]; }
function posPlayers(){ const {M}=st.m; const mp=$('#mp'); if(!mp)return; const bx=M.ball[0], by=M.ball[1];
 mp.querySelectorAll('.pl').forEach(d=>{ const s=+d.dataset.s,i=+d.dataset.i; const e=M.t[s].on[i]; if(!e)return; const [bxr,byr]=roleXY(e.role,i,M.t[s].on);
  const own = s===0?bx:100-bx; let x = e.role==='GK'? 3+Math.max(0,own-50)*0.06 : bxr*0.72+(own-38)*0.38+(M.possSide===s?4:-2);
  let y = byr+(by-50)*0.18; x=Math.max(1.5,Math.min(98.5,x)); if(s===1)x=100-x;
  d.style.left=(x+(Math.random()-.5)*2.5)+'%'; d.style.top=Math.max(3,Math.min(97,y+(Math.random()-.5)*4))+'%'; }); }
function play(){ const m=st.m; if(!m||m.M.done)return; m.paused=false; const b=$('#bpp'); if(b)b.innerHTML=ic('pause'); clearInterval(m.timer); m.timer=setInterval(tick,SPD[m.spd]); }
function pause(){ const m=st.m; if(!m)return; m.paused=true; clearInterval(m.timer); const b=$('#bpp'); if(b)b.innerHTML=ic('play'); }
function pp(){ st.m.paused?play():pause(); }
function spd(){ const m=st.m; m.spd=(m.spd+1)%4; $('#bsp').innerHTML=ic('fast-forward')+' ×'+[1,2,4,8][m.spd]; if(!m.paused)play(); }
function tick(){ const m=st.m; if(!m||st.cur!=='match'){ if(m)clearInterval(m.timer); return; } const M=m.M; const evs=M.step(); updateMatchUI(evs);
 if(evs.some(e=>e.t==='inj'&&e.side===m.side)){ pause(); toast(`🚑 ${_t("Травма! Сделайте замену")}`); subsM(); return; }
 if(evs.some(e=>e.t==='goal')){ const sb=$('#msc'); if(sb){sb.classList.remove('pop');void sb.offsetWidth;sb.classList.add('pop');} }
 if(evs.some(e=>e.t==='ht')&&!M.done){ pause(); toast(M.extra&&M.min>=90?_t("Дополнительное время"):_t("Перерыв — можно изменить тактику")); setTimeout(()=>{ if(st.m===m&&m.paused&&$('#modal').classList.contains('hidden'))play(); },2200); }
 if(M.done){ clearInterval(m.timer); setTimeout(endMatch,1500); } }
function updateMatchUI(evs){ const m=st.m, M=m.M; const sc=$('#msc'); if(!sc)return; $('#sc0').textContent=M.score[0]; $('#sc1').textContent=M.score[1]; $('#mpen').textContent=M.pens?_t("(пен. {0})",M.pens.join(':')):'';
 const IMP={goal:1,save:.45,miss:.35,pk:.5,corner:.22,off:.1}; m.mv=(m.mv||0)*0.8+(M.possSide===0?0.07:-0.07); for(const e of evs){ const w=IMP[e.t]; if(w&&e.side!==undefined) m.mv+=(e.side===0?w:-w); } m.mv=Math.max(-1.2,Math.min(1.2,m.mv)); if(m.mom)m.mom[M.min]=m.mv; momDraw(); tlAdd(evs); $('#mmin').textContent=(M.done?_t("Конец"):M.min+(M.inAdd&&M.addK?'+'+M.addK:'')+"'")+(M.extra&&!M.done?` ${_t("ДВ")}`:'');
 const ball=$('#ball'); const kf=M.kf||[[50,50]]; const dt=SPD[m.spd]/(kf.length+1); kf.forEach((k,i)=>setTimeout(()=>{ if(ball){ball.style.left=k[0]+'%';ball.style.top=k[1]+'%';} },dt*i));
 posPlayers(); const t=M.st[0].poss+M.st[1].poss||1; const p0=Math.round(M.st[0].poss/t*100); $('#pss0').textContent=p0+'%'; $('#pss1').textContent=(100-p0)+'%'; $('#pssb').style.width=p0+'%';
 const q=(n,a,b)=>`<span>${n} <b>${a}–${b}</b></span>`; $('#mst').innerHTML=q(_t("Удары"),M.st[0].sh,M.st[1].sh)+q(_t("В створ"),M.st[0].sot,M.st[1].sot)+q('xG',M.st[0].xg.toFixed(2),M.st[1].xg.toFixed(2))+q(_t("Угловые"),M.st[0].co,M.st[1].co)+q(_t("Фолы"),M.st[0].fo,M.st[1].fo);
 const feed=$('#feed'); for(const e of evs){ if(PREF.brief&&!['goal','yc','rc','sub','inj','ht','ft','kick','pk','var','add'].includes(e.t))continue; const d=document.createElement('div'); if(e.t==='goal')d.className='goal'; d.innerHTML=`<span class="m">${e.ml||e.m}'</span><span class="ei">${evIc(e.t)}</span><span class="f1">${esc(noE(e.txt))}</span>`; feed.prepend(d); }
 while(feed.children.length>120)feed.lastChild.remove(); if(evs.some(e=>e.t==='sub'||e.t==='rc'))drawPlayers(); }
function simEnd(){ const m=st.m; pause(); const M=m.M; M.o.autoUser=true; const all=[]; while(!M.done) all.push(...M.step()); updateMatchUI(all.filter(e=>['goal','rc','ft','pk','sub'].includes(e.t))); setTimeout(endMatch,500); }
function subsM(){ const m=st.m, M=m.M, tm=M.t[m.side]; pause(); st.subSel={};
 const on=tm.on.filter(e=>!e.off); const bench=tm.bench.filter(p=>!M.ps[p.id]);
 modal(`<h2>${_t("Замены · осталось {0}",tm.subsLeft)}</h2><div class="sm mut">${_t("Выберите игрока на поле (слева), затем запасного (справа).")}</div><div class="grid2"><div>${on.map(e=>{const P=M.ps[e.p.id];return `<div class="bp" style="margin:4px 0" id="so${e.p.id}" onclick="UI.subPick('o',${e.p.id})"><span class="pos p${N.POS[e.role][1]}">${N.POS[e.role][0]}</span>${esc(short(e.p))} <span class="${e.p._mfit<65?'red':'mut'}">${Math.round(e.p._mfit)}%</span>${e.inj?'🚑':''}${P.yc?'🟨':''}</div>`}).join('')}</div>
 <div>${bench.map(p=>`<div class="bp" style="margin:4px 0" id="si${p.id}" onclick="UI.subPick('i',${p.id})">${posB(p)}${esc(short(p))} <b>${p.o}</b></div>`).join('')||`<span class="mut sm">${_t("Нет запасных")}</span>`}</div></div>
 <div style="height:10px"></div><button class="btn g w" ${tm.subsLeft>0?'':'disabled'} onclick="UI.doSubBtn()">${_t("Произвести замену")}</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.closeM();UI.play()">${_t("Продолжить матч")}</button>`); }
function subPick(k,id){ st.subSel[k]=id; document.querySelectorAll(`[id^=s${k}]`).forEach(e=>e.classList.remove('sel')); const el=$('#s'+k+id); if(el)el.classList.add('sel'); }
function doSubBtn(){ const m=st.m; const s=st.subSel||{}; if(!s.o||!s.i)return toast(_t("Выберите обоих игроков")); if(m.M.doSub(m.side,s.o,s.i)){ const f=$('#feed'); const d=document.createElement('div'); d.innerHTML=`<span class="m">${m.M.min}'</span><span class="ei">${evIc('sub')}</span><span class="f1">${esc(noE(m.M.ev[m.M.ev.length-1].txt))}</span>`; f.prepend(d); tlAdd([m.M.ev[m.M.ev.length-1]]); drawPlayers(); subsM(); } else toast(_t("Замена невозможна")); }
function tacM(){ const m=st.m; pause(); const tm=m.M.t[m.side]; modal(`<h2>${_t("Тактика по ходу матча")}</h2>${tacPanel(tm.tac,'UI.mTac')}<div class="sm mut">${_t("Схема")}</div><select onchange="UI.mForm(this.value)"><option value="">— ${_t("оставить текущую")} —</option>${Object.keys(N.FORMS).map(f=>`<option>${f}</option>`).join('')}</select>
 <h3 class="sm mut" style="margin-top:10px">${_t("Индивидуальные установки")}</h3>${tm.on.filter(e=>!e.off&&e.role!=='GK').map(e=>`<div class="row sm"><span class="pos p${N.POS[e.role][1]}">${N.POS[e.role][0]}</span><div class="f1">${esc(short(e.p))}</div><select style="width:52%" onchange="UI.mInstr(${e.p.id},this.value)">${Object.entries(INSTR).map(([k,n])=>`<option value="${k}" ${(tm.instr[e.p.id]||'')===k?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}
 <div style="height:10px"></div><button class="btn g w" onclick="UI.closeM();UI.play()">${_t("Продолжить матч")}</button>`); }
function mTac(k,v){ const m=st.m; const tm=m.M.t[m.side]; tm.tac[k]=k==='style'?v:+v; m.M.calc(); }
function mInstr(id,k){ const m=st.m; const tm=m.M.t[m.side]; if(k)tm.instr[id]=k; else delete tm.instr[id]; m.M.calc(); }
function mForm(f){ if(!f)return; const m=st.m; const tm=m.M.t[m.side]; const F=N.FORMS[f]; const on=tm.on.filter(e=>!e.off); const used=new Set();
 const gk=on.find(e=>e.role==='GK'); if(gk)used.add(gk); for(const [role] of F){ if(role==='GK')continue; let best=null,bv=-1; for(const e of on){ if(used.has(e))continue; const v=N.roleOvr(e.p,role); if(v>bv){bv=v;best=e;} } if(best){used.add(best);best.role=role;} }
 m.M.calc(); drawPlayers(); toast(`${_t("Схема изменена")}: ${(f)}`); }
